(function(root){'use strict';
const $=q=>document.querySelector(q),M=root.MetaRules,A=root.AchievementRules;
class MetaUI{
 constructor(ctx){this.ctx=ctx;this.tab='cursor';this.achievementGroup='first';
  $('#stage').insertAdjacentHTML('beforeend','<div class="meta-wallet"><span class="wallet-balance" title="局外金币" role="group" aria-label="局外金币数量"><svg viewBox="0 0 56 58" class="wallet-coin-art" aria-hidden="true"><g stroke="#695631" stroke-width="1.7" stroke-linejoin="round"><path d="m14 32 22-6 12 8-22 8Z" fill="#e6b957"/><path d="M26 42v9l22-8v-9Z" fill="#bb873d"/><path d="m14 32 12 10v9L14 40Z" fill="#d5a247"/><ellipse cx="25" cy="27" rx="17" ry="19" transform="rotate(-19 25 27)" fill="#e7bd62"/><ellipse cx="25" cy="27" rx="12" ry="14" transform="rotate(-19 25 27)" fill="#f6d990" stroke="#c39546"/><path d="m22 20 9 2-2 10-9-2Z" fill="#b18743"/><path d="m23 22 5 1-1 6-5-1Z" fill="#7b794c" stroke="none"/><path d="m16 17 5-4m-8 9 1-2" stroke="#fff1b8" stroke-width="2.4" stroke-linecap="round"/></g></svg><small class="wallet-sr-label">局外金币</small><b id="campaignCoins">0</b></span><button type="button" class="wallet-picture-button" id="walletShopBtn" title="整军备战" aria-label="整军备战" aria-haspopup="dialog" aria-controls="upgradePanel"><span class="wallet-picture wallet-picture-shop" aria-hidden="true"></span><small>整军备战</small></button><button type="button" class="wallet-picture-button" id="walletAchievementsBtn" title="成就任务" aria-label="成就任务" aria-haspopup="dialog" aria-controls="upgradePanel"><span class="wallet-picture wallet-picture-achievements" aria-hidden="true"></span><small>成就</small><b id="achievementBadge" class="wallet-reward-badge" hidden></b></button></div><dialog class="workshop-overlay hidden" id="upgradePanel" role="dialog" aria-modal="true" aria-label="局外升级"><header class="workshop-head"><div><h2>整军备战</h2><p>积累战后金币，兴建营地，固守山河</p></div><span class="workshop-coins">金币 <b id="shopCoins">0</b></span><button id="closeShopBtn" aria-label="关闭升级">×</button></header><nav class="workshop-tabs" aria-label="升级类别">'+[['cursor','采集与营建'],['spells','光标术法'],['wall','城防'],['troop','兵种'],['reserve','开局储备'],['wardrobe','衣冠行装'],['achievements','成就任务']].map(([id,name])=>'<button data-shop-tab="'+id+'" aria-selected="'+(id==='cursor')+'">'+name+'</button>').join('')+'</nav><div class="upgrade-cards" id="upgradeCards"></div><p class="workshop-note" id="upgradeNote"></p></dialog>');
  $('#endCard .result-actions').insertAdjacentHTML('beforeend','<button id="resultWorkshopBtn">整军备战</button>');
  for(const id of ['#walletShopBtn','#resultWorkshopBtn'])$(id).onclick=()=>this.open();$('#walletAchievementsBtn').onclick=()=>this.open('achievements');$('#closeShopBtn').onclick=()=>this.close();
  $('.workshop-tabs').onclick=e=>{const b=e.target.closest('[data-shop-tab]');if(b){if(b.dataset.shopTab==='wardrobe'){this.openWardrobe();return}this.tab=b.dataset.shopTab;this.render()}};
  $('#upgradeCards').onclick=e=>{const filter=e.target.closest('[data-ach-group]'),claim=e.target.closest('[data-ach-claim]');if(filter){this.achievementGroup=filter.dataset.achGroup;this.render();return}if(claim&&!claim.disabled){const r=ctx.claim(claim.dataset.achClaim);this.render();this.note(r.ok?'成就奖励已领取 · +'+r.reward+' 金币':r.reason,!r.ok);return}const b=e.target.closest('[data-upgrade]');if(!b||b.disabled)return;const r=ctx.purchase(b.dataset.upgrade);this.render();this.note(r.ok?'升级完成 · 下一局生效':r.reason,!r.ok)};
  $('#upgradePanel').addEventListener('close',()=>$('#upgradePanel').classList.add('hidden'));
  this.wallet();
 }
 wallet(){$('#campaignCoins').textContent=this.ctx.profile().coins;$('#shopCoins').textContent=this.ctx.profile().coins;const n=A.available(this.ctx.profile().achievements).length;$('#achievementBadge').textContent=n;$('#achievementBadge').hidden=!n;$('#walletAchievementsBtn').setAttribute('aria-label',n?'成就任务，'+n+'项奖励可领取':'成就任务')}
 openWardrobe(){if(!this.ctx.allowed())return false;this.close();this.ctx.wardrobe?.();return true}
 note(message,error=false){$('#upgradeNote').textContent=message;$('#upgradeNote').classList.toggle('error',error)}
 open(tab){if(!this.ctx.allowed())return false;if(tab)this.tab=tab;$('#upgradePanel').classList.remove('hidden');this.render();if(!$('#upgradePanel').open)$('#upgradePanel').showModal();return true}
 close(){$('#upgradePanel').classList.add('hidden');if($('#upgradePanel').open)$('#upgradePanel').close()}
 description(id,levels){const level=levels[id],n=Math.min(M.MAX_LEVEL,level+1),next={...levels,[id]:n},pct=v=>Math.round(v*100)+'%';
  if(root.CombatSkills.spells[id])return root.CombatSkills.description(id,level);
  if(id==='wall')return '城墙生命 '+M.wallHp(levels)+' → '+M.wallHp(next)+' · 3级解锁弓箭塔，6级解锁炮塔';
  if(id==='prep'){const stage=this.ctx.stage();return '首波前 '+M.preparationTime(stage,levels)+(level<M.MAX_LEVEL?' → '+M.preparationTime(stage,next):'')+' 秒 · 波间时间不变';}
  if(id==='mine'||id==='wood'){const label=id==='mine'?'矿石':'木材';return '悬停每秒约 '+M.gatherPerSecond(levels,id).toFixed(1)+(level<M.MAX_LEVEL?' → '+M.gatherPerSecond(next,id).toFixed(1):'')+' '+label;}
  if(id==='startGold'||id==='startWood'){const stage=this.ctx.stage(),resource=id==='startGold'?'gold':'wood',label=id==='startGold'?'矿石':'木材',current=M.startingStock(stage,levels)[resource],after=M.startingStock(stage,next)[resource];return '每局开场 '+current+(level<M.MAX_LEVEL?' → '+after:'')+' '+label;}
  if(id==='attack')return '光标伤害 '+M.attackDamage(levels).toFixed(1)+' → '+M.attackDamage(next).toFixed(1)+'，同时缩短攻击间隔';
  if(['footman','archer','spearman','mage'].includes(id)){const a=M.unitBonus(levels,id),b=M.unitBonus(next,id);return '生命 '+pct(a.hp)+' → '+pct(b.hp)+' · 攻击 '+pct(a.damage)+' → '+pct(b.damage)+'（同类将领也获得加成）'}
  if(id.endsWith('Machine'))return '每台自动产出 '+M.machineRate(levels,id).toFixed(2)+' → '+M.machineRate(next,id).toFixed(2)+' / 秒 · 局内消耗矿石木材制作';
  return (id==='heal'?'持续治疗效率':'工作效率')+' ×'+M.rate(levels,id).toFixed(2)+' → ×'+M.rate(next,id).toFixed(2);
 }
 renderAchievements(p){const state=p.achievements,ready=A.available(state).length,completed=state.claimed.length+ready;
  const filters=Object.entries(A.groups).map(([id,label])=>'<button type="button" data-ach-group="'+id+'" aria-pressed="'+(id===this.achievementGroup)+'">'+label+'</button>').join('');
  const cards=A.definitions.filter(d=>d.group===this.achievementGroup).map(d=>{const value=Math.min(d.target,state.stats[d.key]),claimed=state.claimed.includes(d.id),done=value>=d.target;return '<article class="achievement-card"><div><h3>'+d.title+'</h3><span>+'+d.reward+' 金币</span></div><p>'+d.detail+'</p><progress value="'+value+'" max="'+d.target+'" aria-label="'+d.title+'进度"></progress><footer><small>'+value+' / '+d.target+'</small><button type="button" data-ach-claim="'+d.id+'" '+(!done||claimed?'disabled':'')+'>'+ (claimed?'已领取':done?'领取':'进行中')+'</button></footer></article>'}).join('');
  $('#upgradeCards').innerHTML='<div class="achievement-top"><b>已完成 '+completed+' / '+A.definitions.length+'</b><span>'+ready+' 项可领取</span></div><div class="achievement-filters" aria-label="成就分类">'+filters+'</div><div class="achievement-list">'+cards+'</div>';
  this.note(this.ctx.warning()||'胜负结算后记录进度 · 单局招募取历史最高 · 奖励仅可领一次',!!this.ctx.warning());
 }
 render(){const p=this.ctx.profile(),u=M.unlocks(this.ctx.progress(),p.levels);this.wallet();$('#upgradePanel').dataset.tab=this.tab;document.querySelectorAll('[data-shop-tab]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.shopTab===this.tab)));if(this.tab==='achievements'){this.renderAchievements(p);return}
  let html=M.definitions.filter(d=>d.category===this.tab).map(d=>{const level=p.levels[d.id],price=M.cost(d.id,level),locked=d.category==='machine'&&!u.machines,disabled=locked||price==null||p.coins<price;return '<article class="upgrade-card '+(locked?'locked':'')+'"><header><span class="upgrade-seal">'+d.seal+'</span><div><h3>'+d.name+'</h3><small>Lv.'+level+(level<M.MAX_LEVEL?' → Lv.'+(level+1):' · 满级')+'</small></div></header><p>'+this.description(d.id,p.levels)+'</p><button data-upgrade="'+d.id+'" '+(disabled?'disabled':'')+'>'+(locked?'通过第二章解锁':price==null?'已达满级':'升级 · '+price+' 金币'+(p.coins<price?'（不足）':''))+'</button></article>'}).join('');
  if(this.tab==='wall')html+=[['弓箭塔',3,'arrowTower','射程远、射速快，自动迎击敌人'],['炮塔',6,'cannon','范围炮击，适合拦截成群敌军']].map(([name,level,id,detail])=>'<article class="upgrade-card info"><header><span class="upgrade-seal">'+(level===3?'弩':'炮')+'</span><div><h3>'+name+'</h3><small>'+(u[id]?'已解锁 · 下一局可营建':'城墙达到 Lv.'+level+' 解锁')+'</small></div></header><p>'+detail+'。在局内消耗矿石、木材建造，最多各两座。</p></article>').join('');
  $('#upgradeCards').innerHTML=html;this.note(this.ctx.warning()||'金币在胜负结算时获得 · 升级在开局时固定，本局不会随击杀变化',!!this.ctx.warning());
 }
}
root.MetaUI=MetaUI;
})(window);
